import java.net.*;import java.nio.file.*;import java.util.*;import java.io.*;
public class TribalCheck {
 static int checks;static void check(boolean v,String msg){if(!v)throw new AssertionError(msg);checks++;}
 static final Battle.Ground flat=new Battle.Ground(){public boolean solid(int x,int y){return y>=238;}public int surface(int x,int y){return 238;}public void crater(int x,int y,int r){}};
 static Battle battle(int stage,int diff){var b=new Battle(flat);b.start(true);b.configureOnlineTeam();b.explicitHumans=true;b.units[2].hp=b.units[4].hp=0;b.units[0].human=true;TribalRules.setup(b,stage,diff,true);b.tribalFx=0;return b;}
 static void enemiesDead(Battle b){for(var u:b.units)if(u.team==1)u.hp=0;b.check();}
 static void testRules(){
  for(int diff=0;diff<3;diff++){
   var b=battle(1,diff);check(b.tribalGoal==20,"First encounter requires 20 real knockouts");int killed=0;
   while(b.tribalOutcome<0){int amount=0;for(var u:b.units)if(u.hp>0&&u.team==1)amount++;enemiesDead(b);killed+=amount;if(killed<20)check(!b.over&&b.tribalGoal==20-killed,"Reinforcements preserve remaining kill goal");}
   check(killed==20&&!b.over,"Exactly 20 enemies, then a death/result delay");b.tribalFx=0;b.check();check(b.over&&b.winner==0,"First encounter win");
   b=battle(2,diff);check(b.units[1].npc==TribalRules.BROTHER&&b.units[3].npc==TribalRules.SISTER&&!TribalRules.alive(b,TribalRules.BEAN),"Second encounter is Bulan, not bean protection");
   b.units[1].hp=0;b.check();for(int round=0;round<TribalRules.reviveRounds;round++)TribalRules.round(b);check(b.units[1].hp==b.units[1].maxHp/2,"Surviving sibling can revive the other");
   b.units[1].hp=b.units[3].hp=0;b.check();b.tribalFx=0;b.check();check(b.over&&b.winner==0,"Both Bulan dead wins");
   b=battle(2,diff);TribalRules.summon(b,TribalRules.CHAIN,290);b.active=0;int angle=b.units[0].angle;b.adjustAngle(1);check(angle==b.units[0].angle,"Chain locks angle");b.units[6].hp=0;b.adjustAngle(1);check(angle+1==b.units[0].angle,"Destroy chain unlocks angle");TribalRules.summon(b,TribalRules.FATIGUE,290);b.beginTurn(0);check(b.units[0].energy==b.units[0].maxEnergy-100,"Fatigue drains energy");b.units[6].hp=0;b.beginTurn(0);check(b.units[0].energy==b.units[0].maxEnergy,"Destroy fatigue restores next turn energy");
   b=battle(4,diff);b.units[1].hp=0;b.check();check(!b.over&&b.tribalPhase==2&&b.units[1].npc==TribalRules.RAGE&&!b.input(),"Sulan transforms in the same encounter and blocks input");b.tribalFx=0;
   TribalRules.summon(b,TribalRules.HEAL,260);b.units[1].hp=100;TribalRules.round(b);check(b.units[1].hp>100,"HP totem heals boss");b.units[6].hp=0;b.units[1].hp=100;TribalRules.round(b);check(b.units[1].hp==100,"Destroyed HP totem stops healing");
   TribalRules.summon(b,TribalRules.BOMB,b.units[0].x);int before=b.units[0].hp;TribalRules.round(b);for(int tick=0;tick<40;tick++)b.tickVisuals();check(b.units[6].hp>0,"Bomb first warning round");TribalRules.round(b);check(b.units[6].hp==0&&b.units[0].hp<before,"Bomb second-round detonation");
   b.units[1].hp=0;b.check();check(!b.over&&b.tribalState==TribalRules.DEAD,"Final death pose precedes results");b.tribalFx=0;b.check();check(b.over&&b.winner==0,"Final form win");
  }
 }
 static void testRewards()throws Exception {var store=new CloudStore.Memory();var s=Expansion780Check.session(store,"TribalReward",20);for(int diff=0;diff<3;diff++){String match=UUID.randomUUID().toString();var players=List.<Map<String,Object>>of(Map.of("id",s.id,"team",0));var p=Map.<String,Object>of("match",match,"run",UUID.randomUUID().toString(),"stage",4,"difficulty",diff,"winner",0,"players",players,"min",TribalRules.STONE_MIN[diff],"max",TribalRules.STONE_MAX[diff]);int coins=s.profile.coins;store.tribal("finish",p);store.tribal("finish",p);check(s.profile.coins-coins==200*(diff+1),"Finish retries award once");var deck=(int[])store.tribalStore.matches.get(match).get("deck");check(Arrays.stream(deck).filter(x->x==2).count()==(diff==2?1:0),"At most one Hard wing in whole deck");check(Arrays.stream(deck).filter(x->x==3).count()==(diff==2?6:diff==1?3:0),"Rare spear deck counts");int card=0;while(deck[card]!=0)card++;var request=Map.<String,Object>of("match",match,"user",s.id,"pick",0,"card",card);int stones=s.profile.stones+Arrays.stream(s.profile.craftStones).sum();var first=store.tribal("claim",request);store.tribal("claim",request);int amount=Json.num(first,"amount",0);check(amount>=TribalRules.STONE_MIN[diff]&&amount<=TribalRules.STONE_MAX[diff]&&s.profile.stones+Arrays.stream(s.profile.craftStones).sum()-stones==amount,"Stone range and idempotent receipt");}
 }
 static void testRoom()throws Exception {var store=new CloudStore.Memory();try(var server=new GunnyServer(new InetSocketAddress("127.0.0.1",0),Path.of("backend/assets"),store)){server.clock.shutdownNow();var host=Expansion780Check.session(store,"TribalHost",20);host.tribal=host.flock=host.campaign=true;var r=server.new Room(host,6,2,-1,true);r.kind=3;r.dungeonStage=3;r.strict=true;r.difficulty=0;server.rooms.put(r.id,r);host.room=r.id;r.refreshWaiting();r.start();check(r.map==8&&r.battle.dungeonStage==3,"Room starts native jungle map");check(r.battle.units[2].hp==0&&r.battle.units[4].hp==0,"No phantom allies");var fresh=Expansion780Check.session(store,"Reconnect",20);fresh.id=host.id;fresh.profile=host.profile;fresh.tribal=true;int hp=r.battle.units[0].hp;r.battle.units[0].hp=hp-17;check(TribalDungeon.reconnect(server,host,fresh)&&r.host==fresh&&r.members[0]==fresh&&r.battle.units[0].hp==hp-17,"Reconnect preserves seat, HP and host");
   for(int stage=3;stage<=6;stage++){if(stage!=3){r.phase=0;r.dungeonStage=stage;r.refreshWaiting();r.start();}var b=r.battle;while(!b.over){enemiesDead(b);b.tribalFx=0;}check(b.winner==0,"Stage completion");if(stage==4)TribalDungeon.progress(r);TribalDungeon.settle(server,r,List.copyOf(r.participants));check(r.map==stage+5,"Stage map is separate");}check(!r.beanSaved,"No nonexistent bean-protection encounter is carried forward");}
 }
 public static void main(String[] args)throws Exception{testRules();testRewards();testRoom();System.out.println("PASS: "+checks+" tribal rules, reward and room checks");}
}
